function buildSessions() {
  const grid = document.getElementById('sessionGrid');
  const select = document.getElementById('regSession');
  let n = 0;
  SESSION_DATES.forEach(d => {
    d.slots.forEach(s => {
      n++;
      const t = SLOTS[s];
      const isTBD = s === 'TBD';
      const sessionLabel = isTBD ? `${d.label} 時間確認後公告` : `${d.label} ${t.start}–${t.end}`;
      const card = document.createElement('div');
      card.className = 'session-card bg-white rounded-2xl p-6';
      card.innerHTML = `
        <div class="text-sm font-bold text-accent2 tracking-widest mb-1">第 ${n} 場</div>
        <div class="serif font-black text-3xl text-deep mb-1 flex items-center flex-wrap gap-2">
          <span>${d.label}</span>
          ${d.location ? `<span class="chip inline-flex items-center text-sm font-bold px-3 py-1 rounded-full align-middle"><i class="fa-solid fa-location-dot mr-1"></i>${d.location}</span>` : ''}
        </div>
        <div class="text-inksoft text-base mb-4">${isTBD ? '時間確認後公告' : `${t.start}–${t.end}（共${t.hours}小時）`}</div>
        ${(d.venue || d.address) ? `<div class="text-sm text-inksoft/80 mb-4 flex items-start gap-1.5"><i class="fa-solid fa-location-dot mt-0.5 text-accent2"></i><div>${d.venue ? `<span class="font-bold text-deep">${d.venue}</span>${d.address ? '｜' : ''}` : ''}${d.address || ''}${d.transport ? `<br><span class="text-xs text-inksoft/60">${d.transport}</span>` : ''}</div></div>` : ''}
        <div class="font-bold text-accent2 text-base mb-5">主題：${d.topic}</div>
        ${d.closed ? `<button disabled class="w-full py-3 rounded-full font-bold bg-gray-300 text-gray-500 cursor-not-allowed">已截止報名</button>` : `<button onclick="showRegisterModal('${sessionLabel}')" class="btn-primary w-full py-3 rounded-full font-bold">我要報名這場</button>`}
      `;
      grid.appendChild(card);

      const opt = document.createElement('option');
      opt.value = sessionLabel;
      opt.textContent = sessionLabel;
      opt.dataset.slug = d.slug || '';
      select.appendChild(opt);
    });
  });
}

// 依sessionLabel反查SESSION_DATES裡的場地資訊(地址/費用等)，跟buildSessions()同一套sessionLabel組法
function findSessionMeta(label) {
  for (const d of SESSION_DATES) {
    for (const s of d.slots) {
      const t = SLOTS[s];
      const isTBD = s === 'TBD';
      const sessionLabel = isTBD ? `${d.label} 時間確認後公告` : `${d.label} ${t.start}–${t.end}`;
      if (sessionLabel === label) return d;
    }
  }
  return null;
}

function showRegisterModal(preselect) {
  const modal = document.getElementById('registerModal');
  modal.classList.remove('hidden'); modal.classList.add('flex');
  document.getElementById('registerForm').reset();
  const metaEl = document.getElementById('modalSessionMeta');
  if (preselect) {
    document.getElementById('regSession').value = preselect;
    document.getElementById('modalSessionLabel').textContent = '場次：' + preselect;
    const d = findSessionMeta(preselect);
    if (d && (d.venue || d.address || d.transport)) {
      metaEl.innerHTML = `${d.venue ? `<span class="font-bold">${d.venue}</span>${d.address ? '｜' : ''}` : ''}${d.address || ''}${d.transport ? `<br>${d.transport}` : ''}`;
      metaEl.classList.remove('hidden');
    } else {
      metaEl.innerHTML = ''; metaEl.classList.add('hidden');
    }
  } else {
    document.getElementById('modalSessionLabel').textContent = '選擇場次後送出，資料會直接帶到 LINE';
    metaEl.innerHTML = ''; metaEl.classList.add('hidden');
  }
}
